def format_bytes(n):
    """Return a human-readable byte size string, e.g. '1.5 KB'."""
    for unit, threshold in [('KB', 1024), ('MB', 1024**2), ('GB', 1024**3), ('TB', 1024**4)]:
        if n < threshold:
            value = n / (threshold / 1024)
            if value == int(value):
                return f'{int(value)} {unit}'
            return f'{value:.1f} {unit}'
    return f'{n} B'
